CREATE TABLE publish_snapshots(
 id varchar(36) NOT NULL PRIMARY KEY,brand_id varchar(36) NOT NULL,post_id varchar(36) NOT NULL,revision_id varchar(36) NOT NULL,
 approval_decision_id varchar(36) NOT NULL,actor_id varchar(36) NOT NULL,request_id varchar(36) NOT NULL,authorization_id varchar(36) NOT NULL,destination_id varchar(36) NOT NULL,
 provider enum('META','TIKTOK','YOUTUBE','LINKEDIN') NOT NULL,platform enum('FACEBOOK','INSTAGRAM','TIKTOK','YOUTUBE','LINKEDIN') NOT NULL,operation_type enum('PUBLISH') NOT NULL,approval_decision enum('APPROVED','CHANGES_REQUESTED','REJECTED') NOT NULL,
 authorization_version int unsigned NOT NULL,validation_brand_revision int unsigned NOT NULL,destination_remote_id varbinary(200) NOT NULL,capability_ref varbinary(64) NOT NULL,
 content_json json NOT NULL,options_json json NOT NULL,copy_hash binary(32) NOT NULL,intent_hash binary(32) NOT NULL,request_digest binary(32) NOT NULL,created_at datetime(3) NOT NULL,confirmation_expires_at datetime(3) NOT NULL,
 CONSTRAINT publish_snapshot_ids CHECK((OCTET_LENGTH(id)=36 AND REGEXP_LIKE(id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND (OCTET_LENGTH(brand_id)=36 AND REGEXP_LIKE(brand_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND (OCTET_LENGTH(post_id)=36 AND REGEXP_LIKE(post_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND (OCTET_LENGTH(revision_id)=36 AND REGEXP_LIKE(revision_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND (OCTET_LENGTH(approval_decision_id)=36 AND REGEXP_LIKE(approval_decision_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND (OCTET_LENGTH(actor_id)=36 AND REGEXP_LIKE(actor_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND (OCTET_LENGTH(request_id)=36 AND REGEXP_LIKE(request_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND (OCTET_LENGTH(authorization_id)=36 AND REGEXP_LIKE(authorization_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND (OCTET_LENGTH(destination_id)=36 AND REGEXP_LIKE(destination_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c'))),
 CONSTRAINT publish_snapshot_binding CHECK(provider IN('META','TIKTOK','YOUTUBE','LINKEDIN') AND platform IN('FACEBOOK','INSTAGRAM','TIKTOK','YOUTUBE','LINKEDIN') AND operation_type='PUBLISH' AND approval_decision='APPROVED' AND authorization_version>0 AND validation_brand_revision>0 AND ((provider='META' AND platform IN('FACEBOOK','INSTAGRAM')) OR (provider='TIKTOK' AND platform='TIKTOK') OR (provider='YOUTUBE' AND platform='YOUTUBE') OR (provider='LINKEDIN' AND platform='LINKEDIN'))),
 CONSTRAINT publish_snapshot_value CHECK((OCTET_LENGTH(destination_remote_id) BETWEEN 1 AND 200 AND NOT REGEXP_LIKE(CONVERT(destination_remote_id USING ascii),'[^A-Za-z0-9._:/-]','c')) AND (OCTET_LENGTH(capability_ref) BETWEEN 1 AND 64 AND NOT REGEXP_LIKE(CONVERT(capability_ref USING ascii),'[^A-Za-z0-9._:/-]','c')) AND JSON_TYPE(content_json)='OBJECT' AND JSON_STORAGE_SIZE(content_json)<=32768 AND JSON_TYPE(options_json)='OBJECT' AND JSON_STORAGE_SIZE(options_json)<=4096),
 CONSTRAINT publish_snapshot_confirmation CHECK(confirmation_expires_at>created_at AND confirmation_expires_at<=DATE_ADD(created_at,INTERVAL 10 MINUTE)),
 CONSTRAINT publish_snapshot_brand_fk FOREIGN KEY(brand_id) REFERENCES brands(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT publish_snapshot_revision_fk FOREIGN KEY(post_id,revision_id) REFERENCES content_revisions(post_id,id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT publish_snapshot_variant_fk FOREIGN KEY(revision_id,platform) REFERENCES content_variants(revision_id,platform) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT publish_snapshot_decision_fk FOREIGN KEY(approval_decision_id,post_id,revision_id,approval_decision) REFERENCES content_decisions(id,post_id,revision_id,decision) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT publish_snapshot_actor_fk FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT publish_snapshot_authorization_fk FOREIGN KEY(authorization_id,brand_id,provider) REFERENCES social_authorizations(id,brand_id,provider) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT publish_snapshot_destination_fk FOREIGN KEY(destination_id,authorization_id,brand_id,provider) REFERENCES social_destinations(id,authorization_id,brand_id,provider) ON DELETE RESTRICT ON UPDATE RESTRICT,
 UNIQUE KEY publish_request_once(actor_id,request_id),UNIQUE KEY publish_revision_destination_once(revision_id,destination_id,platform,operation_type),UNIQUE KEY publish_snapshot_revision(id,revision_id),
 INDEX publish_snapshot_workspace(brand_id,created_at,id),INDEX publish_snapshot_post(post_id,revision_id),INDEX publish_snapshot_decision(approval_decision_id,post_id,revision_id,approval_decision),
 INDEX publish_snapshot_auth(authorization_id,brand_id,provider),INDEX publish_snapshot_destination(destination_id,authorization_id,brand_id,provider),INDEX publish_snapshot_variant(revision_id,platform)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
