CREATE TABLE publish_operations(
 id varchar(36) NOT NULL PRIMARY KEY,state enum('CREATED','DISPATCHING','ACCEPTED','PROCESSING','PUBLISHED','FAILED','UNKNOWN') NOT NULL,version int unsigned NOT NULL,last_event_sequence int unsigned NOT NULL,updated_at datetime(3) NOT NULL,
 dispatch_started_at datetime(3) NULL,dispatch_deadline datetime(3) NULL,dispatch_claim_hash binary(32) NULL,last_status_check_at datetime(3) NULL,
 CONSTRAINT publish_operation_bounds CHECK((OCTET_LENGTH(id)=36 AND REGEXP_LIKE(id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND state IN('CREATED','DISPATCHING','ACCEPTED','PROCESSING','PUBLISHED','FAILED','UNKNOWN') AND version>0 AND last_event_sequence BETWEEN 1 AND 100),
 CONSTRAINT publish_operation_dispatch CHECK((dispatch_started_at IS NULL AND dispatch_deadline IS NULL AND dispatch_claim_hash IS NULL AND state IN('CREATED','FAILED')) OR (dispatch_started_at IS NOT NULL AND dispatch_deadline IS NOT NULL AND dispatch_claim_hash IS NOT NULL AND dispatch_deadline>dispatch_started_at AND dispatch_deadline<=DATE_ADD(dispatch_started_at,INTERVAL 30 SECOND) AND state<>'CREATED')),
 CONSTRAINT publish_operation_snapshot_fk FOREIGN KEY(id) REFERENCES publish_snapshots(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 INDEX publish_operations_state(state,updated_at,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
--> statement-breakpoint
CREATE TABLE publish_events(
 operation_id varchar(36) NOT NULL,sequence int unsigned NOT NULL,state enum('CREATED','DISPATCHING','ACCEPTED','PROCESSING','PUBLISHED','FAILED','UNKNOWN') NOT NULL,boundary enum('LOCAL','REMOTE','UNCONFIRMED') NOT NULL,observed_at datetime(3) NOT NULL,
 error_category enum('VALIDATION','LOCAL_DATABASE','AUTHORIZATION','CAPABILITY','MEDIA','REMOTE_REJECTED','REMOTE_PROCESSING','PROVIDER_RATE_LIMIT','TRANSPORT','UNCONFIRMED') NULL,safe_error_code enum('INVALID','UNAVAILABLE','ACCESS_LOST','UNSUPPORTED','RATE_LIMITED','REJECTED','PROCESSING_FAILED','OUTCOME_UNKNOWN') NULL,remote_publication_id varbinary(256) NULL,remote_processing_id varbinary(256) NULL,published_at datetime(3) NULL,
 PRIMARY KEY(operation_id,sequence),
 CONSTRAINT publish_event_bounds CHECK((OCTET_LENGTH(operation_id)=36 AND REGEXP_LIKE(operation_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND sequence BETWEEN 1 AND 100 AND state IN('CREATED','DISPATCHING','ACCEPTED','PROCESSING','PUBLISHED','FAILED','UNKNOWN') AND boundary IN('LOCAL','REMOTE','UNCONFIRMED') AND (error_category IS NULL OR (error_category IS NOT NULL AND error_category IN('VALIDATION','LOCAL_DATABASE','AUTHORIZATION','CAPABILITY','MEDIA','REMOTE_REJECTED','REMOTE_PROCESSING','PROVIDER_RATE_LIMIT','TRANSPORT','UNCONFIRMED'))) AND (safe_error_code IS NULL OR (safe_error_code IS NOT NULL AND safe_error_code IN('INVALID','UNAVAILABLE','ACCESS_LOST','UNSUPPORTED','RATE_LIMITED','REJECTED','PROCESSING_FAILED','OUTCOME_UNKNOWN')))),
 CONSTRAINT publish_event_references CHECK((remote_publication_id IS NULL OR (remote_publication_id IS NOT NULL AND (OCTET_LENGTH(remote_publication_id) BETWEEN 1 AND 256 AND NOT REGEXP_LIKE(CONVERT(remote_publication_id USING ascii),'[^A-Za-z0-9._:/-]','c')))) AND (remote_processing_id IS NULL OR (remote_processing_id IS NOT NULL AND (OCTET_LENGTH(remote_processing_id) BETWEEN 1 AND 256 AND NOT REGEXP_LIKE(CONVERT(remote_processing_id USING ascii),'[^A-Za-z0-9._:/-]','c')))) AND (published_at IS NULL OR (published_at IS NOT NULL AND published_at<=observed_at))),
 CONSTRAINT publish_event_outcome CHECK((state='PUBLISHED' AND boundary='REMOTE' AND remote_publication_id IS NOT NULL AND published_at IS NOT NULL AND error_category IS NULL AND safe_error_code IS NULL) OR (state IN('ACCEPTED','PROCESSING') AND boundary='REMOTE' AND (remote_publication_id IS NOT NULL OR remote_processing_id IS NOT NULL) AND published_at IS NULL AND error_category IS NULL AND safe_error_code IS NULL) OR (state='FAILED' AND boundary IN('LOCAL','REMOTE') AND error_category IS NOT NULL AND safe_error_code IS NOT NULL AND published_at IS NULL) OR (state='UNKNOWN' AND boundary='UNCONFIRMED' AND error_category IS NOT NULL AND error_category IN('TRANSPORT','UNCONFIRMED') AND safe_error_code IS NOT NULL AND safe_error_code='OUTCOME_UNKNOWN' AND published_at IS NULL) OR (state IN('CREATED','DISPATCHING') AND boundary='LOCAL' AND error_category IS NULL AND safe_error_code IS NULL AND remote_publication_id IS NULL AND remote_processing_id IS NULL AND published_at IS NULL)),
 CONSTRAINT publish_event_operation_fk FOREIGN KEY(operation_id) REFERENCES publish_operations(id) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
