CREATE TABLE publish_assets(
 snapshot_id varchar(36) NOT NULL,revision_id varchar(36) NOT NULL,media_id varchar(36) NOT NULL,position tinyint unsigned NOT NULL,
 mime enum('image/jpeg','image/png','image/webp','video/mp4') NOT NULL,byte_size int unsigned NOT NULL,sha256 binary(32) NOT NULL,width int unsigned NOT NULL,height int unsigned NOT NULL,duration_ms int unsigned NULL,
 created_at datetime(3) NOT NULL,protected_until datetime(3) NOT NULL,PRIMARY KEY(snapshot_id,media_id),
 CONSTRAINT publish_asset_ids CHECK((OCTET_LENGTH(snapshot_id)=36 AND REGEXP_LIKE(snapshot_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND (OCTET_LENGTH(revision_id)=36 AND REGEXP_LIKE(revision_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND (OCTET_LENGTH(media_id)=36 AND REGEXP_LIKE(media_id,'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','c')) AND position BETWEEN 0 AND 3),
 CONSTRAINT publish_asset_value CHECK(mime IN('image/jpeg','image/png','image/webp','video/mp4') AND byte_size BETWEEN 1 AND 33554432 AND width BETWEEN 1 AND 8192 AND height BETWEEN 1 AND 8192 AND width*height<=16777216 AND ((mime='video/mp4' AND duration_ms IS NOT NULL AND duration_ms BETWEEN 1 AND 600000 AND width<=3840 AND height<=2160) OR (mime IN('image/jpeg','image/png','image/webp') AND duration_ms IS NULL AND byte_size<=8388608))),
 CONSTRAINT publish_asset_hold CHECK(protected_until>created_at AND protected_until<=DATE_ADD(created_at,INTERVAL 24 HOUR)),
 CONSTRAINT publish_asset_snapshot_fk FOREIGN KEY(snapshot_id,revision_id) REFERENCES publish_snapshots(id,revision_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT publish_asset_revision_fk FOREIGN KEY(revision_id,media_id) REFERENCES content_revision_media(revision_id,media_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 UNIQUE KEY publish_asset_order(snapshot_id,position),INDEX publish_asset_hold(media_id,protected_until,snapshot_id),INDEX publish_asset_revision(revision_id,media_id),INDEX publish_asset_snapshot(snapshot_id,revision_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
